set -eu; . /etc/minio/minio.env; . /root/thanos-s3-credentials; until curl -fsS --cacert /root/thanos-ca.crt https://10.100.255.13:9000/minio/health/ready >/dev/null; do sleep 1; done; mc alias set local https://10.100.255.13:9000 "$MINIO_ROOT_USER" "$MINIO_ROOT_PASSWORD" --api S3v4 --insecure >/dev/null; mc mb --ignore-existing local/thanos-metrics >/dev/null; cat > /tmp/thanos-metrics-policy.json <<'POLICY'
{
  "Version": "2012-10-17",
  "Statement": [
    {"Effect":"Allow","Action":["s3:GetBucketLocation","s3:ListBucket","s3:ListBucketMultipartUploads"],"Resource":["arn:aws:s3:::thanos-metrics"]},
