  ]
}
POLICY
mc admin policy create local thanos-metrics-policy /tmp/thanos-metrics-policy.json >/dev/null 2>&1 || true; mc admin user add local "$S3_ACCESS_KEY" "$S3_SECRET_KEY" >/dev/null 2>&1 || true; mc admin policy attach local thanos-metrics-policy --user "$S3_ACCESS_KEY" >/dev/null; rm -f /tmp/thanos-metrics-policy.json; rm -rf /root/.mc; test -d /srv/thanos-objectstore/thanos-metrics; echo bucket-and-user-ready

